try:
 import selfies
 ss=['[C][I]','[O][=C][C][=C][Branch1][C][I][C][=C][NH1][Ring1][#Branch1]','[C][C][O][C][Branch1][C][C][=O]','[C][N][Branch1][C][C][C][=O]','[O][=C][Branch1][C][O-1][O-1]']
 for s in ss:
  sm=selfies.decoder(s)
  print(s,'=>',sm)
  try:
   from rdkit import Chem
   m=Chem.MolFromSmiles(sm)
   print(Chem.MolToSmiles(m) if m else 'invalid')
  except Exception as e: print(e)
except Exception as e: print(type(e).__name__,e)
